     1→//! Project automation tasks
     2→//!
     3→//! All commands default to debug builds and verbose output.
     4→//! Use `-r` for release builds, `-q` for quiet output.
     5→//!
     6→//! # Usage
     7→//!
     8→//! ```text
     9→//! cargo xtask build                 # build all crates
    10→//! cargo xtask build ex-x1 -r        # build specific crate (release)
    11→//! cargo xtask build ex-x2 -opt -r   # build ex-x2 with nightly optimizations
    12→//!
    13→//! cargo xtask run hw-x1             # run specific crate (shows exit code)
    14→//! cargo xtask run .                 # run crate in current directory
    15→//!
    16→//! cargo xtask test                  # test all crates
    17→//! cargo xtask test ex-x1 -q         # test specific crate (quiet)
    18→//! cargo xtask test rlibc-x2         # includes rlibc-x2-tests binaries
    19→//! ```
    20→//!
    21→//! # Available Commands
    22→//!
    23→//! - `build` - Build crates (one at a time)
    24→//! - `run` - Build and run crates (shows exit code)
    25→//! - `test` - Run tests (with summary)
    26→//!
    27→//! # Optimized Builds (-opt flag)
    28→//!
    29→//! The `-opt` or `--optimized` flag enables nightly optimizations that dramatically
    30→//! reduce binary size by eliminating Rust's panic formatting machinery.
    31→//!
    32→//! Sizes for ex-* apps (minimal 3-byte exit code programs):
    33→//!
    34→//! | Target | Baseline | Optimized | Reduction |
    35→//! |--------|----------|-----------|-----------|
    36→//! | glibc  | ~298 KB  | ~9 KB     | 97%       |
    37→//! | musl   | ~381 KB  | ~23 KB    | 94%       |
    38→//! | x2     | ~40 KB   | ~6 KB     | 85%       |
    39→//!
    40→//! Works with: `-x2`, `-glibc`, and `-musl` crates (not `-x1` which is already no_std).
    41→//!
    42→//! Uses:
    43→//! - Nightly Rust toolchain
    44→//! - `-Z build-std=std,core,panic_abort` (rebuild std from source)
    45→//! - `-C panic=immediate-abort` (skip panic formatting)
    46→
    47→use std::fs;
    48→use std::io::Write;
    49→use std::path::Path;
    50→use std::process::{Command, ExitCode, Stdio};
    51→
    52→enum Subcommand {
    53→    Build,
    54→    Run,
    55→    Test,
    56→}
    57→
    58→struct Config {
    59→    subcommand: Subcommand,
    60→    quiet: bool,
    61→    fail_fast: bool,
    62→    debug: bool,
    63→    optimized: bool,       // Use nightly + build-std + panic-immediate-abort
    64→    strip: bool,           // Strip debug symbols from binaries after building
    65→    verbose_compile: bool, // Show compiler/linker command lines
    66→    crates: Vec<String>,   // Empty means all crates
    67→}
    68→
    69→struct TestResult {
    70→    name: String,
    71→    passed: bool,
    72→    #[allow(dead_code)] // Captured for potential future use (e.g., detailed failure reports)
    73→    output: String,
    74→}
    75→
    76→fn main() -> ExitCode {
    77→    let config = parse_args();
    78→
    79→    // Get workspace root (xtask is at workspace root level)
    80→    let workspace_root = Path::new(env!("CARGO_MANIFEST_DIR"))
    81→        .parent()
    82→        .expect("Could not find workspace root");
    83→
    84→    let cmd_name = match config.subcommand {
    85→        Subcommand::Build => "build",
    86→        Subcommand::Run => "run",
    87→        Subcommand::Test => "test",
    88→    };
    89→
    90→    // Get list of crates to operate on
    91→    let crates = if config.crates.is_empty() {
    92→        get_all_crates(workspace_root)
    93→    } else {
    94→        config.crates.clone()
    95→    };
    96→
    97→    // Run command on each crate
    98→    let mut results = Vec::new();
    99→    for crate_name in &crates {
   100→        // Skip lib-only crates for run command
   101→        if cmd_name == "run" && !crate_has_binary(crate_name, workspace_root) {
   102→            continue;
   103→        }
   104→
   105→        let result = run_cargo_on_crate(cmd_name, crate_name, workspace_root, &config);
   106→        let failed = !result.passed;
   107→        results.push(result);
   108→        if failed && config.fail_fast {
   109→            break;
   110→        }
   111→    }
   112→
   113→    // For test, also run rlibc-x2-tests if rlibc-x2 was included
   114→    if matches!(config.subcommand, Subcommand::Test) {
   115→        let should_run_rlibc_x2_tests = if config.crates.is_empty() {
   116→            true // Running all tests
   117→        } else {
   118→            config.crates.iter().any(|c| c == "rlibc-x2")
   119→        };
   120→
   121→        if should_run_rlibc_x2_tests {
   122→            let rlibc_x2_results = run_rlibc_x2_tests(workspace_root, &config);
   123→            for result in rlibc_x2_results {
   124→                let failed = !result.passed;
   125→                results.push(result);
   126→                if failed && config.fail_fast {
   127→                    break;
   128→                }
   129→            }
   130→        }
   131→    }
   132→
   133→    // Only show summary for test command
   134→    if matches!(config.subcommand, Subcommand::Test) {
   135→        print_summary(&results)
   136→    } else {
   137→        // For build/run, just return success/failure based on results
   138→        if results.iter().any(|r| !r.passed) {
   139→            ExitCode::from(1)
   140→        } else {
   141→            ExitCode::SUCCESS
   142→        }
   143→    }
   144→}
   145→
   146→/// Get list of all crates in the workspace (excludes xtask and test crates)
   147→fn get_all_crates(workspace_root: &Path) -> Vec<String> {
   148→    // These are the crates we want to build/run/test
   149→    let crates = [
   150→        "ex-x1",
   151→        "ex-x2",
   152→        "ex-glibc",
   153→        "ex-musl",
   154→        "hw-x1",
   155→        "hw-x2",
   156→        "hw-glibc",
   157→        "hw-musl",
   158→        "rlibc-x1",
   159→        "rlibc-x2",
   160→        "is-libc-used",
   161→    ];
   162→
   163→    // Filter to crates that exist
   164→    crates
   165→        .iter()
   166→        .filter(|name| {
   167→            get_crate_path(name, workspace_root)
   168→                .join("Cargo.toml")
   169→                .exists()
   170→        })
   171→        .map(|s| s.to_string())
   172→        .collect()
   173→}
   174→
   175→/// Get the path to a crate directory
   176→fn get_crate_path(name: &str, workspace_root: &Path) -> std::path::PathBuf {
   177→    if name.starts_with("ex-") || name.starts_with("hw-") {
   178→        workspace_root.join("apps").join(name)
   179→    } else if name == "is-libc-used" {
   180→        workspace_root.join("tools").join(name)
   181→    } else {
   182→        workspace_root.join(name)
   183→    }
   184→}
   185→
   186→/// Check if a crate has a binary (src/main.rs)
   187→fn crate_has_binary(name: &str, workspace_root: &Path) -> bool {
   188→    get_crate_path(name, workspace_root)
   189→        .join("src/main.rs")
   190→        .exists()
   191→}
   192→
   193→/// Run a cargo command on a single crate
   194→fn run_cargo_on_crate(
   195→    cmd_name: &str,
   196→    crate_name: &str,
   197→    workspace_root: &Path,
   198→    config: &Config,
   199→) -> TestResult {
   200→    let is_musl = crate_name.contains("musl");
   201→    let is_glibc = crate_name.contains("glibc");
   202→    let is_x2 = crate_name.ends_with("-x2");
   203→    let is_x1 = crate_name.ends_with("-x1");
   204→
   205→    // -opt works for any crate except x1 (which is already no_std)
   206→    let use_optimized = config.optimized && !is_x1;
   207→
   208→    let target_info = if use_optimized {
   209→        if is_musl {
   210→            " (musl, optimized)"
   211→        } else if is_glibc {
   212→            " (glibc, optimized)"
   213→        } else if is_x2 {
   214→            " (optimized)"
   215→        } else {
   216→            " (gnu, optimized)"
   217→        }
   218→    } else if is_musl {
   219→        " (musl)"
   220→    } else {
   221→        ""
   222→    };
   223→
   224→    println!("=== {crate_name}{target_info} ===");
   225→
   226→    let mut cmd = Command::new("cargo");
   227→
   228→    // Use nightly toolchain for optimized builds
   229→    if use_optimized {
   230→        cmd.arg("+nightly");
   231→    }
   232→
   233→    cmd.arg(cmd_name);
   234→
   235→    if !config.debug {
   236→        cmd.arg("--release");
   237→    }
   238→
   239→    if config.verbose_compile {
   240→        cmd.arg("-v");
   241→    }
   242→
   243→    cmd.args(["-p", crate_name]);
   244→
   245→    if use_optimized {
   246→        // All optimized builds use build-std to rebuild std with panic=immediate-abort
   247→        cmd.args(["-Z", "build-std=std,core,panic_abort"]);
   248→
   249→        // Generate a linker "version script" to make all symbols LOCAL except _start.
   250→        // This allows --gc-sections to remove more unreferenced functions.
   251→        //
   252→        // The linker should have a simple flag like "--executable-hide-symbols" that
   253→        // automatically makes all symbols local except the entry point. Instead, we
   254→        // must create a "version script" file with arcane syntax.
   255→        let target_dir = workspace_root.join("target");
   256→        let _ = fs::create_dir_all(&target_dir);
   257→        let version_config = target_dir.join("opt-version.config");
   258→        if let Ok(mut f) = fs::File::create(&version_config) {
   259→            let _ = writeln!(f, "{{ global: _start; local: *; }};");
   260→        }
   261→
   262→        let rustflags = format!(
   263→            "-C panic=immediate-abort -Z unstable-options -C link-arg=-Wl,--gc-sections -C link-arg=-Wl,--version-script={}",
   264→            version_config.display()
   265→        );
   266→        cmd.env("RUSTFLAGS", &rustflags);
   267→
   268→        // Select target based on crate type
   269→        if is_x2 {
   270→            cmd.args(["-Z", "panic-immediate-abort"]);
   271→            let target_json = workspace_root.join("x86_64-unknown-linux-rlibcx2.json");
   272→            cmd.arg("--target");
   273→            cmd.arg(&target_json);
   274→        } else if is_musl {
   275→            cmd.args(["--target", "x86_64-unknown-linux-musl"]);
   276→        } else {
   277→            // glibc and other crates use gnu target
   278→            cmd.args(["--target", "x86_64-unknown-linux-gnu"]);
   279→        }
   280→    } else if is_musl {
   281→        // Non-optimized musl builds
   282→        cmd.args(["--target", "x86_64-unknown-linux-musl"]);
   283→    }
   284→
   285→    cmd.current_dir(workspace_root);
   286→
   287→    // Capture mtime before build for strip decision on run command
   288→    let binary_path = get_binary_path(crate_name, workspace_root, config);
   289→    let mtime_before = get_mtime(&binary_path);
   290→
   291→    if config.quiet {
   292→        cmd.stdout(Stdio::piped());
   293→        cmd.stderr(Stdio::piped());
   294→
   295→        match cmd.output() {
   296→            Ok(output) => {
   297→                let passed = output.status.success();
   298→                let exit_code = output.status.code().unwrap_or(-1);
   299→                let stderr = String::from_utf8_lossy(&output.stderr);
   300→
   301→                if cmd_name == "run" {
   302→                    println!("  exit code: {exit_code}");
   303→                    // Only strip if binary was rebuilt (mtime changed)
   304→                    let mtime_after = get_mtime(&binary_path);
   305→                    let was_rebuilt = mtime_after > mtime_before;
   306→                    if config.strip && was_rebuilt {
   307→                        strip_binary(crate_name, workspace_root, config);
   308→                    }
   309→                } else if passed {
   310→                    if cmd_name == "build" {
   311→                        println!("  {}", binary_path.display());
   312→                    }
   313→                    if config.strip {
   314→                        strip_binary(crate_name, workspace_root, config);
   315→                    }
   316→                }
   317→                if !passed && cmd_name != "run" {
   318→                    println!("  FAILED");
   319→                    eprintln!("{stderr}");
   320→                }
   321→
   322→                TestResult {
   323→                    name: crate_name.to_string(),
   324→                    passed,
   325→                    output: stderr.to_string(),
   326→                }
   327→            }
   328→            Err(e) => {
   329→                eprintln!("  Failed to run cargo {cmd_name}: {e}");
   330→                TestResult {
   331→                    name: crate_name.to_string(),
   332→                    passed: false,
   333→                    output: e.to_string(),
   334→                }
   335→            }
   336→        }
   337→    } else {
   338→        // Verbose mode - show all output
   339→        let status = cmd.status();
   340→        let (passed, exit_code) = match &status {
   341→            Ok(s) => (s.success(), s.code().unwrap_or(-1)),
   342→            Err(_) => (false, -1),
   343→        };
   344→
   345→        if cmd_name == "run" {
   346→            println!("  exit code: {exit_code}");
   347→            // Only strip if binary was rebuilt (mtime changed)
   348→            let mtime_after = get_mtime(&binary_path);
   349→            let was_rebuilt = mtime_after > mtime_before;
   350→            if config.strip && was_rebuilt {
   351→                strip_binary(crate_name, workspace_root, config);
   352→            }
   353→        } else if passed {
   354→            if cmd_name == "build" {
   355→                println!("  {}", binary_path.display());
   356→            }
   357→            if config.strip {
   358→                strip_binary(crate_name, workspace_root, config);
   359→            }
   360→        }
   361→        println!();
   362→
   363→        TestResult {
   364→            name: crate_name.to_string(),
   365→            passed,
   366→            output: String::new(),
   367→        }
   368→    }
   369→}
   370→
   371→/// Get the path to the built binary
   372→fn get_binary_path(crate_name: &str, workspace_root: &Path, config: &Config) -> std::path::PathBuf {
   373→    let profile = if config.debug { "debug" } else { "release" };
   374→    let is_musl = crate_name.contains("musl");
   375→    let is_x2 = crate_name.ends_with("-x2");
   376→    let is_x1 = crate_name.ends_with("-x1");
   377→    let use_optimized = config.optimized && !is_x1;
   378→
   379→    let target_subdir = if is_musl {
   380→        "x86_64-unknown-linux-musl"
   381→    } else if use_optimized && is_x2 {
   382→        "x86_64-unknown-linux-rlibcx2"
   383→    } else if use_optimized {
   384→        // glibc, tools, and other optimized crates use gnu target
   385→        "x86_64-unknown-linux-gnu"
   386→    } else {
   387→        ""
   388→    };
   389→
   390→    if target_subdir.is_empty() {
   391→        workspace_root.join(format!("target/{profile}/{crate_name}"))
   392→    } else {
   393→        workspace_root.join(format!("target/{target_subdir}/{profile}/{crate_name}"))
   394→    }
   395→}
   396→
   397→/// Get the mtime of a file, if it exists
   398→fn get_mtime(path: &Path) -> Option<std::time::SystemTime> {
   399→    fs::metadata(path).ok().and_then(|m| m.modified().ok())
   400→}
   401→
   402→/// Strip debug symbols from the built binary
   403→fn strip_binary(crate_name: &str, workspace_root: &Path, config: &Config) {
   404→    let binary_path = get_binary_path(crate_name, workspace_root, config);
   405→
   406→    if binary_path.exists() {
   407→        let status = Command::new("strip").arg(&binary_path).status();
   408→        match status {
   409→            Ok(s) if s.success() => {
   410→                if !config.quiet
   411→                    && let Ok(meta) = fs::metadata(&binary_path)
   412→                {
   413→                    println!("  stripped: {} bytes", meta.len());
   414→                }
   415→            }
   416→            _ => {
   417→                eprintln!("  warning: failed to strip {}", binary_path.display());
   418→            }
   419→        }
   420→    }
   421→}
   422→
   423→fn parse_args() -> Config {
   424→    let args: Vec<String> = std::env::args().skip(1).collect();
   425→    let mut args_iter = args.iter();
   426→
   427→    // Parse subcommand (first argument)
   428→    let subcommand = match args_iter.next().map(|s| s.as_str()) {
   429→        Some("build") => Subcommand::Build,
   430→        Some("run") => Subcommand::Run,
   431→        Some("test") => Subcommand::Test,
   432→        Some("-h" | "--help") => {
   433→            print_main_help();
   434→            std::process::exit(0);
   435→        }
   436→        Some(other) => {
   437→            eprintln!("Unknown command: {other}");
   438→            eprintln!("Use --help for usage information");
   439→            std::process::exit(1);
   440→        }
   441→        None => {
   442→            print_main_help();
   443→            std::process::exit(0);
   444→        }
   445→    };
   446→
   447→    let mut config = Config {
   448→        subcommand,
   449→        quiet: false,
   450→        fail_fast: false,
   451→        debug: true, // Default to debug for faster iteration; use -r for release
   452→        optimized: false,
   453→        strip: false,
   454→        verbose_compile: false,
   455→        crates: Vec::new(),
   456→    };
   457→
   458→    // Parse options and positional arguments for the subcommand
   459→    for arg in args_iter {
   460→        match arg.as_str() {
   461→            "-q" | "--quiet" => config.quiet = true,
   462→            "-f" | "--fail-fast" | "--fail" => config.fail_fast = true,
   463→            "-r" | "--release" => config.debug = false,
   464→            "-d" | "--debug" => config.debug = true,
   465→            "-opt" | "--optimized" => config.optimized = true,
   466→            "-s" | "--strip" => config.strip = true,
   467→            "-vc" | "--verbose-compile" => config.verbose_compile = true,
   468→            "-h" | "--help" => {
   469→                match config.subcommand {
   470→                    Subcommand::Build => print_cmd_help("build"),
   471→                    Subcommand::Run => print_cmd_help("run"),
   472→                    Subcommand::Test => print_test_help(),
   473→                }
   474→                std::process::exit(0);
   475→            }
   476→            other if other.starts_with('-') => {
   477→                eprintln!("Unknown option: {other}");
   478→                eprintln!("Use --help for usage information");
   479→                std::process::exit(1);
   480→            }
   481→            "." => {
   482→                match resolve_current_crate() {
   483→                    Ok(Some(name)) => config.crates.push(name),
   484→                    Ok(None) => {} // Workspace root - leave crates empty for "all"
   485→                    Err(e) => {
   486→                        eprintln!("{e}");
   487→                        std::process::exit(1);
   488→                    }
   489→                }
   490→            }
   491→            crate_name => {
   492→                config.crates.push(crate_name.to_string());
   493→            }
   494→        }
   495→    }
   496→
   497→    config
   498→}
   499→
   500→/// Resolve "." to the crate name in the current directory
   501→/// Returns None if at workspace root (meaning "all"), Some(name) for a crate, or error
   502→fn resolve_current_crate() -> Result<Option<String>, String> {
   503→    let cargo_toml = std::env::current_dir()
   504→        .map_err(|e| format!("Failed to get current directory: {e}"))?
   505→        .join("Cargo.toml");
   506→
   507→    if !cargo_toml.exists() {
   508→        return Err("No Cargo.toml found in current directory".to_string());
   509→    }
   510→
   511→    let content =
   512→        fs::read_to_string(&cargo_toml).map_err(|e| format!("Failed to read Cargo.toml: {e}"))?;
   513→
   514→    // Simple parsing - look for name = "..." in [package] section
   515→    let mut in_package = false;
   516→    for line in content.lines() {
   517→        let line = line.trim();
   518→        if line == "[package]" {
   519→            in_package = true;
   520→            continue;
   521→        }
   522→        if line.starts_with('[') {
   523→            in_package = false;
   524→            continue;
   525→        }
   526→        if in_package && line.starts_with("name") {
   527→            // Parse: name = "crate-name"
   528→            if let Some(eq_pos) = line.find('=') {
   529→                let value = line[eq_pos + 1..].trim();
   530→                let value = value.trim_matches('"').trim_matches('\'');
   531→                return Ok(Some(value.to_string()));
   532→            }
   533→        }
   534→    }
   535→
   536→    // No [package] section - likely workspace root, treat as "all"
   537→    Ok(None)
   538→}
   539→
   540→fn print_main_help() {
   541→    println!("Usage: cargo xtask <COMMAND> [OPTIONS]");
   542→    println!();
   543→    println!("Commands:");
   544→    println!("  build   Build crates");
   545→    println!("  run     Build and run crates");
   546→    println!("  test    Run tests");
   547→    println!();
   548→    println!("Options:");
   549→    println!("  -h, --help    Show this help");
   550→    println!();
   551→    println!("Run 'cargo xtask <COMMAND> --help' for command-specific options");
   552→}
   553→
   554→fn print_cmd_help(cmd: &str) {
   555→    println!("Usage: cargo xtask {cmd} [OPTIONS] [CRATES]...");
   556→    println!();
   557→    println!("Run 'cargo {cmd}' on crates. With no crates specified, {cmd}s all.");
   558→    println!();
   559→    println!("Arguments:");
   560→    println!("  [CRATES]...       Crates to {cmd} (e.g., ex-x1, hw-x2)");
   561→    println!("                    Use '.' for the crate in the current directory");
   562→    println!("                    Musl target auto-detected from crate name");
   563→    println!();
   564→    println!("Options:");
   565→    println!("  -q, --quiet       Suppress output (default is verbose)");
   566→    println!("  -f, --fail-fast   Stop on first failure");
   567→    println!("  -d, --debug       Use debug builds (default)");
   568→    println!("  -r, --release     Use release builds");
   569→    println!("  -opt, --optimized Use nightly optimizations (x2, glibc, musl crates)");
   570→    println!("  -s, --strip       Strip debug symbols from binaries after building");
   571→    println!("  -h, --help        Show this help");
   572→    println!();
   573→    println!("Examples:");
   574→    println!("  cargo xtask {cmd}               # {cmd} all");
   575→    println!("  cargo xtask {cmd} .             # {cmd} crate in current directory");
   576→    println!("  cargo xtask {cmd} ex-x1         # {cmd} ex-x1 only");
