   611→fn run_rlibc_x2_tests(workspace_root: &Path, config: &Config) -> Vec<TestResult> {
   612→    let mut results = Vec::new();
   613→
   614→    println!("=== rlibc-x2-tests ===");
   615→
   616→    // First, build the test binaries
   617→    print!("  Building rlibc-x2-tests... ");
   618→
   619→    let mut build_cmd = Command::new("cargo");
   620→    build_cmd.args(["build", "-p", "rlibc-x2-tests"]);
   621→    if !config.debug {
   622→        build_cmd.arg("--release");
   623→    }
   624→    let build_output = build_cmd
   625→        .current_dir(workspace_root)
   626→        .stdout(Stdio::piped())
   627→        .stderr(Stdio::piped())
   628→        .output();
   629→
   630→    match build_output {
   631→        Ok(output) if output.status.success() => {
   632→            println!("ok");
   633→        }
   634→        Ok(output) => {
   635→            println!("FAILED");
   636→            let stderr = String::from_utf8_lossy(&output.stderr);
   637→            eprintln!("{stderr}");
   638→            results.push(TestResult {
   639→                name: "rlibc-x2-tests (build)".to_string(),
   640→                passed: false,
   641→                output: stderr.to_string(),
   642→            });
   643→            return results;
   644→        }
   645→        Err(e) => {
   646→            println!("FAILED");
   647→            eprintln!("  Failed to run cargo build: {e}");
   648→            results.push(TestResult {
   649→                name: "rlibc-x2-tests (build)".to_string(),
   650→                passed: false,
   651→                output: e.to_string(),
   652→            });
   653→            return results;
   654→        }
   655→    }
   656→
   657→    // Find and run test binaries
   658→    let profile = if config.debug { "debug" } else { "release" };
   659→    let target_dir = workspace_root.join(format!("target/{profile}"));
   660→
   661→    let test_binaries: Vec<_> = fs::read_dir(&target_dir)
   662→        .into_iter()
   663→        .flatten()
   664→        .filter_map(|e| e.ok())
   665→        .filter(|e| {
   666→            let name = e.file_name();
   667→            let name = name.to_string_lossy();
   668→            name.ends_with("-tests") && e.path().is_file()
   669→        })
   670→        .collect();
   671→
   672→    if test_binaries.is_empty() {
   673→        eprintln!("  No test binaries found in {}", target_dir.display());
   674→        results.push(TestResult {
   675→            name: "rlibc-x2-tests (no binaries)".to_string(),
   676→            passed: false,
   677→            output: String::new(),
   678→        });
   679→        return results;
   680→    }
   681→
   682→    for entry in test_binaries {
   683→        let path = entry.path();
   684→        let name = entry.file_name();
   685→        let name_str = name.to_string_lossy();
   686→
   687→        print!("  Running {name_str}... ");
   688→
   689→        let output = Command::new(&path)
   690→            .stdout(Stdio::piped())
   691→            .stderr(Stdio::piped())
   692→            .output();
   693→
   694→        match output {
   695→            Ok(output) => {
   696→                let passed = output.status.success();
   697→                let stdout = String::from_utf8_lossy(&output.stdout);
   698→                let stderr = String::from_utf8_lossy(&output.stderr);
   699→                let combined = format!("{stdout}{stderr}");
   700→
   701→                if passed {
   702→                    println!("ok");
   703→                    if !config.quiet && !stdout.is_empty() {
   704→                        println!("{stdout}");
   705→                    }
   706→                } else {
   707→                    println!("FAILED");
   708→                    println!("{combined}");
   709→                }
   710→
   711→                results.push(TestResult {
   712→                    name: format!("rlibc-x2-tests/{name_str}"),
   713→                    passed,
   714→                    output: combined.to_string(),
   715→                });
   716→            }
   717→            Err(e) => {
   718→                println!("FAILED");
   719→                let output = format!("Failed to run: {e}");
   720→                eprintln!("  {output}");
   721→                results.push(TestResult {
   722→                    name: format!("rlibc-x2-tests/{name_str}"),
   723→                    passed: false,
   724→                    output,
   725→                });
   726→            }
   727→        }
   728→    }
   729→
   730→    println!();
   731→    results
   732→}
   733→
   734→fn print_summary(results: &[TestResult]) -> ExitCode {
   735→    println!("========================================");
   736→    println!("               SUMMARY");
   737→    println!("========================================\n");
   738→
   739→    let mut passed_count = 0;
   740→    let mut failed_count = 0;
   741→
   742→    for result in results {
   743→        let status = if result.passed {
   744→            passed_count += 1;
   745→            "PASS"
   746→        } else {
   747→            failed_count += 1;
   748→            "FAIL"
   749→        };
   750→        println!("  [{status}] {}", result.name);
   751→    }
   752→
   753→    println!(
   754→        "\n  Total: {} passed, {} failed",
